#include "simp/Ast.hpp"

#include <ostream>

namespace simp {
namespace {

void indent(std::ostream& output, int depth) {
    for (int index = 0; index < depth; ++index) {
        output << "  ";
    }
}

const char* expressionName(ExpressionKind kind) {
    switch (kind) {
    case ExpressionKind::Integer: return "Integer";
    case ExpressionKind::String: return "String";
    case ExpressionKind::Identifier: return "Identifier";
    case ExpressionKind::Unary: return "Unary";
    case ExpressionKind::Binary: return "Binary";
    }
    return "Expression";
}

void dumpExpression(const Expression& expression, std::ostream& output, int depth) {
    indent(output, depth);
    output << expressionName(expression.kind);
    if (!expression.value.empty()) {
        output << " [" << expression.value << "]";
    }
    if (expression.formattedString) {
        output << " [formatted]";
    }
    output << '\n';
    if (expression.left) {
        dumpExpression(*expression.left, output, depth + 1);
    }
    if (expression.right) {
        dumpExpression(*expression.right, output, depth + 1);
    }
}

void dumpStatements(const std::vector<Statement>& statements, std::ostream& output, int depth);

void dumpStatement(const Statement& statement, std::ostream& output, int depth) {
    indent(output, depth);
    switch (statement.kind) {
    case StatementKind::Declaration:
        output << "Declaration [" << statement.declaredType << " " << statement.name << "]\n";
        break;
    case StatementKind::Assignment:
        output << "Assignment [" << statement.name << "]\n";
        break;
    case StatementKind::Print: output << "Print\n"; break;
    case StatementKind::If: output << "If\n"; break;
    case StatementKind::While: output << "While\n"; break;
    case StatementKind::Block: output << "Block\n"; break;
    }
    for (const auto& expression : statement.expressions) {
        dumpExpression(*expression, output, depth + 1);
    }
    if (!statement.body.empty()) {
        dumpStatements(statement.body, output, depth + 1);
    }
    if (statement.hasAlternate) {
        indent(output, depth + 1);
        output << "Else\n";
        dumpStatements(statement.alternate, output, depth + 2);
    }
}

void dumpStatements(const std::vector<Statement>& statements, std::ostream& output, int depth) {
    for (const auto& statement : statements) {
        dumpStatement(statement, output, depth);
    }
}

} // namespace

void dumpAst(const Program& program, std::ostream& output) {
    output << "Program\n";
    dumpStatements(program.statements, output, 1);
}

} // namespace simp
